DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='team_boss_tick'; d:=replace(d,'guarded boolean;','guarded boolean; protection numeric;'); d:=replace(d,'UPDATE public.team_boss_players SET hp=greatest(0,hp-CASE WHEN guarded THEN floor(hit*0.35)::integer ELSE hit END) WHERE run_id=p_run AND profile_id=q.profile_id;','SELECT min(CASE WHEN p.role=''guardian'' THEN 0.35 ELSE 0.60 END) INTO protection FROM public.team_boss_questions z JOIN public.team_boss_players p USING(run_id,profile_id) WHERE z.run_id=p_run AND z.round=r.round AND z.is_correct AND z.action=''guard'' AND z.target_id=q.profile_id; UPDATE public.team_boss_players SET hp=greatest(0,hp-floor(hit*coalesce(protection,1))::integer) WHERE run_id=p_run AND profile_id=q.profile_id;'); EXECUTE d; END $$;